custom_qss:
/* ============================================================
   NEONHALO — fake neon glow via stacked borders + outline.
   box-shadow is ignored by Krita, so the halo is faked: a bright
   thin border plus an outline drawn outside it, layered on every
   panel so edges look like they bleed light. Hot magenta core,
   electric-cyan secondary, near-black base.
   ============================================================ */

* { color: #f2e6f5; }
QAbstractScrollArea, QFrame, QStackedWidget, QScrollArea, QTabWidget, QWidget {
    background: transparent; border: none;
}

/* window: deep void */
QMainWindow { background: #07050a !important; border: none; }
QDialog { background: #0e0a14 !important; border: 1px solid #ff2d95; outline: 2px solid #a01560; }

/* menubar: cyan edge on selected */
QMenuBar { background: #0a0710 !important; border: none; border-bottom: 1px solid #a01560; }
QMenuBar::item { padding: 5px 14px; background: transparent !important; color: #8a6a96; }
QMenuBar::item:selected { background: #160f20 !important; color: #22e0ff; }
QMenuBar::item:disabled { color: #4a3550; }

/* popup menus: halo-framed */
QMenu { background: #0e0a14 !important; border: 1px solid #ff2d95; outline: 2px solid #a01560; padding: 6px; font-size: 12px;}
QMenu::item { padding: 7px 26px 7px 14px; background: transparent !important; color: #f2e6f5; }
QMenu::item:selected { background: #3d0a26 !important; color: #ff2d95; }
QMenu::item:disabled { color: #4a3550; }
QMenu::separator { height: 1px; background: #a01560; margin: 6px 10px; }

/* toolbar: flat, cyan active */
QToolBar { background: #0a0710 !important; border: none; border-bottom: 1px solid #a01560; spacing: 3px; padding: 4px; }
QToolBar::separator { background: #a01560; width: 1px; margin: 6px 5px; }
QToolBar QToolButton, QToolButton { background: transparent !important; padding: 6px 12px; border: 1px solid transparent; color: #c79ec7; font-size: 12px;}
QToolBar QToolButton:hover, QToolButton:hover { background: #160f20 !important; border: 1px solid #22e0ff; color: #22e0ff; }
QToolBar QToolButton:checked, QToolBar QToolButton:pressed,
QToolButton:checked, QToolButton:pressed { background: #3d0a26 !important; border: 1px solid #ff2d95; color: #ff2d95; }

/* buttons: halo cards, magenta hover */
QPushButton {
    background: #0e0a14 !important;
    border: 1px solid #a01560; outline: 2px solid #3d0a26; border-radius: 4px; padding: 8px 22px;
    color: #f2e6f5; font-weight: 600; font-size: 12px;}
QPushButton:hover { background: #3d0a26 !important; border: 1px solid #ff2d95; outline: 2px solid #a01560; color: #ff2d95; }
QPushButton:pressed { background: #ff2d95 !important; color: #07050a; outline: 2px solid #a01560; }
QPushButton:checked { background: #3d0a26 !important; border: 1px solid #ff2d95; color: #ff2d95; }
QPushButton:default { border: 1px solid #22e0ff; outline: 2px solid #3d0a26; }
QPushButton:disabled { background: #0a0710 !important; color: #4a3550; border: 1px solid #a01560; outline: none; }

/* inputs: halo wells, cyan focus */
QLineEdit, QSpinBox, QDoubleSpinBox, QTextEdit, QPlainTextEdit {
    background: #050308 !important;
    border: 1px solid #a01560; outline: 2px solid #3d0a26; border-radius: 4px; padding: 7px 12px;
    color: #22e0ff; selection-background-color: #ff2d95; selection-color: #07050a; font-size: 12px;}
QLineEdit:focus, QSpinBox:focus, QDoubleSpinBox:focus, QTextEdit:focus, QPlainTextEdit:focus { border: 1px solid #22e0ff; outline: 2px solid #a01560; }
QLineEdit:disabled, QSpinBox:disabled, QDoubleSpinBox:disabled, QTextEdit:disabled, QPlainTextEdit:disabled { color: #4a3550; }
QSpinBox::up-button, QSpinBox::down-button, QDoubleSpinBox::up-button, QDoubleSpinBox::down-button { background: transparent !important; border: none; width: 16px; }

QComboBox { background: #050308 !important; border: 1px solid #a01560; outline: 2px solid #3d0a26; border-radius: 4px; padding: 7px 12px; color: #f2e6f5; font-size: 12px;}
QComboBox:hover { border: 1px solid #ff2d95; }
QComboBox:focus { border: 1px solid #22e0ff; outline: 2px solid #a01560; }
QComboBox::drop-down { border: none; background: transparent !important; width: 18px; }
QComboBox QAbstractItemView { background: #0e0a14 !important; border: 1px solid #ff2d95; outline: 2px solid #a01560; padding: 5px; selection-background-color: #3d0a26; selection-color: #ff2d95; font-size: 12px;}

QCheckBox, QRadioButton { color: #f2e6f5; background: transparent !important; padding: 3px; }
QCheckBox::indicator, QRadioButton::indicator { width: 16px; height: 16px; border-radius: 3px; background: #050308 !important; border: 1px solid #a01560; }
QRadioButton::indicator { border-radius: 8px; }
QCheckBox::indicator:hover, QRadioButton::indicator:hover { border: 1px solid #22e0ff; }
QCheckBox::indicator:checked, QRadioButton::indicator:checked { background: #ff2d95 !important; border: 1px solid #ff2d95; }

QTabBar::tab { background: transparent !important; color: #8a6a96; padding: 9px 18px; border: 1px solid transparent; }
QTabBar::tab:hover { color: #22e0ff; }
QTabBar::tab:selected { color: #ff2d95; border: 1px solid #ff2d95; border-bottom: 2px solid #ff2d95; }
QTabWidget::pane { border: none; border-top: 1px solid #a01560; }

/* docks: halo-framed panels */
QDockWidget { background: #0e0a14 !important; border: 1px solid #a01560; outline: 2px solid #3d0a26; border-radius: 4px; }
QDockWidget::title {
    background: #0a0710 !important;
    border: none; border-bottom: 1px solid #a01560; border-left: 3px solid #ff2d95;
    padding: 7px 12px; color: #ff2d95; font-weight: 700;
}
QDockWidget::close-button, QDockWidget::float-button { background: transparent !important; border: 1px solid transparent; border-radius: 3px; padding: 3px; icon-size: 16px; }
QDockWidget::close-button:hover, QDockWidget::float-button:hover { background: #3d0a26 !important; }

QGroupBox { background: transparent !important; border: 1px solid #a01560; outline: 2px solid #3d0a26; border-radius: 4px; margin-top: 13px; padding-top: 11px; }
QGroupBox::title { subcontrol-origin: margin; subcontrol-position: top left; padding: 0 10px; color: #22e0ff; font-weight: 700; background: #07050a; }

QAbstractItemView { background: #050308 !important; border: 1px solid #a01560; outline: 2px solid #3d0a26; border-radius: 4px; outline: none; alternate-background-color: #0a0710; selection-background-color: #3d0a26; selection-color: #ff2d95; }
QAbstractItemView::item { padding: 6px 12px; border: none; color: #f2e6f5; }
QAbstractItemView::item:hover { background: #160f20 !important; color: #22e0ff; }
QAbstractItemView::item:selected { background: #3d0a26 !important; color: #ff2d95; }
QTreeView::branch { background: transparent !important; }
QHeaderView::section { background: #0a0710 !important; border: none; border-bottom: 1px solid #ff2d95; padding: 7px 12px; color: #22e0ff; font-weight: 700; }

QScrollBar:vertical { background: #050308; width: 11px; margin: 0; border: none; }
QScrollBar::handle:vertical { background: #a01560; border-radius: 2px; min-height: 32px; }
QScrollBar::handle:vertical:hover { background: #ff2d95; }
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical { height: 0; border: none; background: none; }
QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical { background: none; }
QScrollBar:horizontal { background: #050308; height: 11px; margin: 0; border: none; }
QScrollBar::handle:horizontal { background: #a01560; border-radius: 2px; min-width: 32px; }
QScrollBar::handle:horizontal:hover { background: #ff2d95; }
QScrollBar::add-line:horizontal, QScrollBar::sub-line:horizontal { width: 0; border: none; background: none; }
QScrollBar::add-page:horizontal, QScrollBar::sub-page:horizontal { background: none; }
QScrollBar::corner { background: none; }

QSlider::groove:horizontal { background: #050308; border: 1px solid #a01560; height: 8px; border-radius: 4px; }
QSlider::sub-page:horizontal { background: #ff2d95; border-radius: 4px; }
QSlider::add-page:horizontal { background: #050308; border-radius: 4px; }
QSlider::handle:horizontal { background: #ff2d95; width: 14px; height: 16px; margin: -6px 0; border: 2px solid #07050a; border-radius: 9px; }
QSlider::handle:horizontal:hover { background: #22e0ff; }
QSlider::groove:vertical { background: #050308; border: 1px solid #a01560; width: 8px; border-radius: 4px; }
QSlider::sub-page:vertical { background: #ff2d95; border-radius: 4px; }
QSlider::handle:vertical { background: #ff2d95; width: 16px; height: 14px; margin: 0 -6px; border: 2px solid #07050a; border-radius: 9px; }

QProgressBar { background: #050308; border: 1px solid #a01560; border-radius: 4px; text-align: center; color: #22e0ff; font-size: 11px; min-height: 16px; }
QProgressBar::chunk { background: #ff2d95; border-radius: 3px; }

QStatusBar { background: #0a0710 !important; border-top: 1px solid #a01560; color: #8a6a96; font-size: 11px; }
QStatusBar::item { border: none; }
QToolTip { background: #0e0a14 !important; border: 1px solid #ff2d95; outline: 2px solid #a01560; border-radius: 4px; padding: 6px 12px; color: #f2e6f5; }
QSplitter::handle { background: #a01560; }
QSplitter::handle:hover { background: #ff2d95; }
QListView, QListWidget, QTreeWidget, QTableWidget { background: #050308 !important; border: 1px solid #a01560; outline: 2px solid #3d0a26; border-radius: 4px; outline: none; }
